
import { useTranslation } from '@fanfanlo';
import { ScriptEditor } from '../../../script-editor';
import { scriptActionSimpleTemplate, scriptActionAdvancedTemplate, scriptActionFullTemplate } from '../scriptTemplates';
import { IActionScriptData } from './IActionScript.inft';

export function IActionScriptUI(data: IActionScriptData) {
  const { t } = useTranslation('droid-project/iproject/actions/script/script-action/content');

  return (
    <ScriptEditor
      data={data}
      simpleTemplate={scriptActionSimpleTemplate}
      advancedTemplate={scriptActionAdvancedTemplate}
      fullTemplate={scriptActionFullTemplate}
      simpleModeDescription={t('IActionScriptUI.modeDescription_simple')}
      advancedModeDescription={t('IActionScriptUI.modeDescription_advanced')}
      fullModeDescription={t('IActionScriptUI.modeDescription_full')}
      type="action"
      rows={12}
    />
  );
}
