import { Log } from "@fanfanlo"
import _ from "lodash"
import { ulid } from "ulid"
import { INameId } from "../common"
import { createDefaultTriggerActionGroup, ITriggerActionGroup, mergeTriggerActionGroupToDefaultData } from "../trigger-action/ITriggerActionGroup"
import { ProjectCategory } from "./ProjectCategory"

const fileLog = new Log(true, 'IProject.data_f');
fileLog.pause = false;

export interface IProjectJavaData {
}

export interface IProjectShellData{
    id:string
}
export interface IProjectData extends INameId{
    id:string
    client_id:string
    type:string
    /** Project 类别 */
    category?:ProjectCategory
    originId?:string
    // localName?:string
    triggerActionGroup:ITriggerActionGroup
    keepAlive?:boolean
}

export function createProjectDefaultData():IProjectData{
    return {
        type:'project',
        id:ulid(),
        client_id:ulid(),
        triggerActionGroup:createDefaultTriggerActionGroup()
    }

}

export function mergeProjectDataToDefaultData(data:Partial<IProjectData>):IProjectData{
    const result = _.merge(createProjectDefaultData(), data);
    result.triggerActionGroup = mergeTriggerActionGroupToDefaultData(result.triggerActionGroup)
    return result
}

/**
 * 根据 ProjectCategory 创建 Project 默认数据
 * @param category 项目类别
 */
export function createProjectByCategory(category: ProjectCategory): IProjectData {
    fileLog.log(`[createProjectByCategory] 创建项目, category=${category}`);

    const base = createProjectDefaultData();
    base.category = category;
    fileLog.log(`[createProjectByCategory] 基础数据已创建, client_id=${base.client_id}, category=${base.category}`);

    switch (category) {
        case ProjectCategory.QuickAction:
            // 快捷操作：清空 trigger，只保留 action
            fileLog.log(`[createProjectByCategory] QuickAction: 清空 triggerGroup`);
            base.triggerActionGroup.list[0].triggerGroup.list = [];
            break;

        case ProjectCategory.ScriptRunner:
            // 脚本运行器：清空 trigger，action 的 script 类型将在 UI 层强制设置
            fileLog.log(`[createProjectByCategory] ScriptRunner: 清空 triggerGroup`);
            base.triggerActionGroup.list[0].triggerGroup.list = [];
            break;

        case ProjectCategory.Workflow:
            // 工作流：默认结构，无需修改
            fileLog.log(`[createProjectByCategory] Workflow: 使用默认结构`);
            break;

        default:
            fileLog.log(`[createProjectByCategory] 未知类别: ${category}, 使用默认结构`);
            break;
    }

    fileLog.log(`[createProjectByCategory] 项目创建完成:`, JSON.stringify(base));
    return base;
}
