import { ulid } from "ulid";
import { createActionUtils, IActionData, IActionJavaData, IActionShellData } from "@droid/project-interface";
import { scriptNamespace } from "../script-namespace";
import { IActionScriptUI } from "./IActionScript.UI";

const type = `${scriptNamespace}script`

export interface IActionScriptJavaData extends IActionJavaData {
  script: string
  scriptMode: 'simple' | 'advanced' | 'full'
}

export interface IActionScriptData extends IActionData<IActionShellData, IActionScriptJavaData> {
  javaData: IActionScriptJavaData
}

function createDefaultData(): IActionScriptData {
  console.log('[IActionScript.createDefaultData] 开始创建默认数据')

  const id = ulid()
  console.log('[IActionScript.createDefaultData] 生成id:', id)

  const defaultData: IActionScriptData = {
    id,
    type,
    name: 'actionScript',
    javaData: {
      script: '',
      scriptMode: 'simple'
    }
  }
  console.log('[IActionScript.createDefaultData] defaultData:', defaultData)
  return defaultData
}

function init() {
}

export const actionScriptUtils = createActionUtils(type, init, createDefaultData, IActionScriptUI)
