import { ulid } from "ulid";
import { INameId } from "../common";
import { IGroup } from "../common/IGroup.intf";
import { createDefaultTriggerAction, ITriggerAction } from "../trigger-action/ITriggerAction.intf";
import { mergeToDefaultData } from "../utils/mergeToDefaultData";
export const triggerActionGroupType = 'triggerActionGroup'
export interface ITriggerActionGroup extends IGroup<ITriggerAction>, INameId{
    type:string
    id:string
}

export function createDefaultTriggerActionGroup():ITriggerActionGroup{
    return {
        type:triggerActionGroupType,
        id:ulid(),
        name:'',
        list:[createDefaultTriggerAction()],
        checks:[[true]],
        isSequential:false
    }
}

export function mergeTriggerActionGroupToDefaultData(data:Partial<ITriggerActionGroup>):ITriggerActionGroup{
    return mergeToDefaultData(createDefaultTriggerActionGroup, data)
}