import { Log } from '@fanfanlo'
import { actionOpenAppUtils } from '../actions/app/action-open-app/IActionOpenApp.inft'
import { actionToAppMainPageUtils } from '../actions/app/to-app-main-page/IToAppMainPage.intf'
import { actionA11yNodeExecuteUtils } from '../actions/a11y/node-execute/node-execute'
import { actionNodeActionUtils } from '../actions/a11y/node-action/IActionNodeAction'
import { actionScriptUtils } from '../actions/script/script-action/IActionScript.inft'

const fileLog = new Log(false, 'initActions_f')
fileLog.pause = true
fileLog.childrenPaused = true

/**
 * 初始化所有 Actions
 * 调用各个 actionUtils.init() 完成注册
 */
export function initActions() {
    fileLog.log('[initActions] 开始初始化所有 action types')

    actionOpenAppUtils.init()
    fileLog.log('[initActions] actionOpenAppUtils 初始化完成')

    actionToAppMainPageUtils.init()
    fileLog.log('[initActions] actionToAppMainPageUtils 初始化完成')

    actionA11yNodeExecuteUtils.init()
    fileLog.log('[initActions] actionA11yNodeExecuteUtils 初始化完成')

    actionNodeActionUtils.init()
    fileLog.log('[initActions] actionNodeActionUtils 初始化完成')

    actionScriptUtils.init()
    fileLog.log('[initActions] actionScriptUtils 初始化完成')

    fileLog.log('[initActions] 所有 action types 初始化完成')
}
