import { Log } from "@fanfanlo";
import { IActionOrTriggerListPageParams } from "@app/static";

const fileLog = new Log(false, 'actionUtils_f');
fileLog.pause = true;
fileLog.childrenPaused = true;

/**
 * Action 数据变更属性接口
 */
export interface IOnChangeActionJavaDataProps{
    query:IActionOrTriggerListPageParams,
    // 采用projectEventUtils.dispatchEditEvent的目的是能够在页面刷新后依然能通过url数据更新javaData，但是如果使用注入函数的方法就做不到这点了，所以这个参数当前分析是不要用，以后如果要启用，需要先考虑一下上面用projectEventUtils.dispatchEditEvent的优点是否能被替代才行。
    // 但是现在也面临修改数据后，其它未被修改的数据会需要重新初始化的问题，而projectEventUtils.dispatchEditEvent里是merge，并没有重新初始化其它数据的功能。
    //再次论证。这个方法现在是刷新页面即丢失的，并不是能够通过url来更新数据的。所以似乎可以启用这个方法
    // onJavaDataChangeDataSelect?:(data:any)=>void
    //尝试考虑用这个方式来替代上面注入函数的修改方式。
    //查找到action后，用action proxy的dispatcher派发事件来更新数据
    onDataSelectedEventType?:string
}

/**
 * Action 工具函数接口
 * 注意：这是 v1 兼容接口，用于支持旧代码
 */
export interface IActionUtils<T = any>{
    type:string
    init:()=>void
    mergeDataToDefaultData:(data:Partial<T>)=>T
    createDefaultData:()=>T
    create:(actionGroup:any, data?:Partial<T>)=>void
    update(action:T, data?:Partial<T>):void
    UI:(data:T)=>React.ReactNode
    //点击更改按钮后调用不是page页面的时候需要，例如更改返回首页.
    onClickChange?:(data:IOnChangeActionJavaDataProps, ...rest:any[])=>void
    // 添加异步加载国际化文本的方法
    loadI18nTexts?: (data: T) => Promise<void>
}

/**
 * Action 工具函数映射表
 */
export interface IActionUtilsMap{
    [key:string]:IActionUtils<any>
}

export const ActionUtilsMap:IActionUtilsMap = {}

/**
 * 注册 Action 工具函数
 */
export function registerActionUtils(key:string,utils:IActionUtils<any>){
    const fnLog = fileLog.sub(false, 'registerActionUtils_fn');
    fnLog.log('注册 key:', key);

    if(key in ActionUtilsMap){
        fnLog.error('ActionUtilsMap already has key:', key);
        throw new Error(`ActionUtilsMap already has key: ${key}`)
    }
    ActionUtilsMap[key] = utils
    fnLog.log('注册成功, 当前所有keys:', Object.keys(ActionUtilsMap));
}

/**
 * 获取 Action 工具函数
 */
export function getActionUtils<T = any>(key:string):IActionUtils<T>{
    const fnLog = fileLog.sub(false, 'getActionUtils_fn');
    fnLog.log('查找key:', key);

    const utils = ActionUtilsMap[key]
    if (!utils) {
        fnLog.log('未找到, 可用的keys:', Object.keys(ActionUtilsMap));
    } else {
        fnLog.log('找到');
    }
    return utils
}

/**
 * 创建 Action 工具函数
 * 注意：这是 v1 兼容函数，用于支持旧代码
 */
export function createActionUtils<T = any>(
    type:string,
    init:()=>void,
    createDefaultData:()=>T,
    UI:(data:T)=>React.ReactNode
):IActionUtils<T>{
    const fnLog = fileLog.sub(false, 'createActionUtils_fn');
    fnLog.log('创建 Action Utils, type:', type);

    const res:IActionUtils<T> = {
        type,
        mergeDataToDefaultData:(data:Partial<T>)=>{
            const fnLog2 = fnLog.sub(false, 'mergeDataToDefaultData_fn');
            fnLog2.log('mergeDataToDefaultData, data:', data);
            const defaultData = createDefaultData();
            return Object.assign(defaultData, data);
        },
        createDefaultData,
        create:(actionGroup:any, data?:Partial<T>)=>{
            const fnLog2 = fnLog.sub(false, 'create_fn');
            fnLog2.log('create, data:', data);
            const action = createDefaultData()
            if (actionGroup && actionGroup.list) {
                actionGroup.list.push(action)
            }
        },
        update:(action:T, data?:Partial<T>)=>{
            const fnLog2 = fnLog.sub(false, 'update_fn');
            fnLog2.log('update, data:', data);
            if (data) {
                Object.assign(action, data);
            }
        },
        UI,
        init,
    }
    registerActionUtils(type,res)
    return res
}
